const data = $input.first().json;
const materialName = data.material_name || '';
const category = data.category || '';
const qualityTier = data.quality_tier || 'media';
const encoded = encodeURIComponent(materialName);
const searchUrl = `https://www.leroymerlin.es/buscador.aspx?s=${encoded}`;
return [{ json: {
  material_name: materialName,
  category: category,
  quality_tier: qualityTier,
  search_url: searchUrl,
  jina_url: `https://r.jina.ai/${searchUrl}`
}}];

const resp = $input.first().json;
const markdown = (resp.data || resp.body || '').toString();
const materialName = $('Build Search URL').first().json.material_name;
const pricePattern = /(\d+[,.]?\d*)\s*[€$](?:\s*\/\s*m[²2])?/g;
const prices = [];
let match;
while ((match = pricePattern.exec(markdown)) !== null) {
  const val = parseFloat(match[1].replace(',', '.'));
  if (val > 0.5 && val < 50000) prices.push(val);
}
prices.sort((a, b) => a - b);
const validPrices = prices.slice(0, 20);
const minPrice = validPrices.length > 0 ? Math.min(...validPrices) : null;
const maxPrice = validPrices.length > 0 ? Math.max(...validPrices) : null;
const avgPrice = validPrices.length > 0
  ? Math.round(validPrices.reduce((a, b) => a + b, 0) / validPrices.length * 100) / 100
  : null;
return [{ json: {
  material_name: materialName,
  category: $('Build Search URL').first().json.category,
  quality_tier: $('Build Search URL').first().json.quality_tier,
  web_min_price: minPrice,
  web_max_price: maxPrice,
  web_avg_price: avgPrice,
  prices_found: validPrices.length,
  source_url: $('Build Search URL').first().json.search_url
}}];

const allItems = $input.all();
const webData = $('Parse Web Prices').first().json;
const catalogItems = allItems.filter(i => i.json.id && i.json.unit_price);
const catalogPrices = catalogItems.map(i => parseFloat(i.json.unit_price)).filter(p => p > 0);
const catalogMin = catalogPrices.length > 0 ? Math.min(...catalogPrices) : null;
const catalogMax = catalogPrices.length > 0 ? Math.max(...catalogPrices) : null;
const catalogAvg = catalogPrices.length > 0
  ? Math.round(catalogPrices.reduce((a, b) => a + b, 0) / catalogPrices.length * 100) / 100
  : null;
const finalMin = catalogMin !== null ? catalogMin : webData.web_min_price;
const finalMax = catalogMax !== null ? catalogMax : webData.web_max_price;
const finalAvg = catalogAvg !== null ? catalogAvg : webData.web_avg_price;
const source = catalogItems.length > 0 ? 'catalog' : (webData.prices_found > 0 ? 'web_search' : 'not_found');
return [{ json: {
  material_name: webData.material_name,
  category: webData.category,
  min_price: finalMin,
  avg_price: finalAvg,
  max_price: finalMax,
  source: source,
  source_url: source === 'web_search' ? webData.source_url : null,
  catalog_matches: catalogItems.length,
  web_prices_found: webData.prices_found
}}];
